def pair_sum(prices, target):
    i, j = 0, len(prices) - 1
    while i < j:
        s = prices[i] + prices[j]
        if s == target:
            return (i, j)
        if s < target:
            i += 1
        else:
            j -= 1
    return None

def dedup_sorted(ids):
    if not ids:
        return 0
    w = 1
    for r in range(1, len(ids)):
        if ids[r] != ids[w - 1]:
            ids[w] = ids[r]
            w += 1
    del ids[w:]
    return w

def move_zeros(nums):
    w = 0
    for r in range(len(nums)):
        if nums[r] != 0:
            nums[w], nums[r] = nums[r], nums[w]
            w += 1

def split_by_limit(nums, limit):
    i, j = 0, len(nums) - 1
    while i <= j:
        if nums[i] < limit:
            i += 1
        elif nums[j] >= limit:
            j -= 1
        else:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
            j -= 1
    return i

def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

def is_subsequence(word, text):
    i = 0
    for j in range(len(text)):
        if i < len(word) and text[j] == word[i]:
            i += 1
    return i == len(word)

def best_pair_sum(prices, budget):
    prices = sorted(prices)
    i, j = 0, len(prices) - 1
    best = -1
    while i < j:
        s = prices[i] + prices[j]
        if s <= budget:
            best = max(best, s)
            i += 1
        else:
            j -= 1
    return best

def window_sums(nums, k):
    if k < 1 or k > len(nums):
        raise ValueError("k должно быть от 1 до len(nums)")
    total = sum(nums[:k])
    sums = [total]
    for r in range(k, len(nums)):
        total += nums[r] - nums[r - k]
        sums.append(total)
    return sums

def best_window(nums, k):
    if k < 1 or k > len(nums):
        raise ValueError("k должно быть от 1 до len(nums)")
    total = sum(nums[:k])
    best, start = total, 0
    for r in range(k, len(nums)):
        total += nums[r] - nums[r - k]
        if total > best:
            best, start = total, r - k + 1
    return (start, best)

def max_events(times, w):
    if w <= 0:
        raise ValueError("w должно быть больше 0")
    best = 0
    l = 0
    for r in range(len(times)):
        while times[r] - times[l] >= w:
            l += 1
        best = max(best, r - l + 1)
    return best

def min_difference(scores, k):
    scores = sorted(scores)
    best = scores[k - 1] - scores[0]
    for i in range(1, len(scores) - k + 1):
        best = min(best, scores[i + k - 1] - scores[i])
    return best

def longest_within(nums, limit):
    if limit < 0:
        raise ValueError("limit должно быть не меньше 0")
    best = 0
    total = 0
    l = 0
    for r in range(len(nums)):
        total += nums[r]
        while total > limit:
            total -= nums[l]
            l += 1
        best = max(best, r - l + 1)
    return best

def shortest_window(nums, s):
    if s < 1:
        raise ValueError("s должно быть не меньше 1")
    best = 0
    total = 0
    l = 0
    for r in range(len(nums)):
        total += nums[r]
        while total >= s:
            length = r - l + 1
            if best == 0 or length < best:
                best = length
            total -= nums[l]
            l += 1
    return best

def longest_unique(text):
    count = {}
    best = 0
    l = 0
    for r in range(len(text)):
        ch = text[r]
        count[ch] = count.get(ch, 0) + 1
        while count[ch] > 1:
            count[text[l]] -= 1
            l += 1
        best = max(best, r - l + 1)
    return best

def total_fruit(fruits):
    count = {}
    best = 0
    l = 0
    for r in range(len(fruits)):
        f = fruits[r]
        count[f] = count.get(f, 0) + 1
        while len(count) > 2:
            count[fruits[l]] -= 1
            if count[fruits[l]] == 0:
                del count[fruits[l]]
            l += 1
        best = max(best, r - l + 1)
    return best

def max_frequency(nums, k):
    count = {}
    best = 0
    l = 0
    for r in range(len(nums)):
        x = nums[r]
        count[x] = count.get(x, 0) + 1
        while count[x] > k:
            count[nums[l]] -= 1
            l += 1
        best = max(best, r - l + 1)
    return best

def min_operations(nums, x):
    target = sum(nums) - x
    if target < 0:
        return -1
    best = -1
    total = 0
    l = 0
    for r in range(len(nums)):
        total += nums[r]
        while total > target:
            total -= nums[l]
            l += 1
        if total == target:
            best = max(best, r - l + 1)
    return -1 if best == -1 else len(nums) - best

def shortest_all_kinds(nums):
    need = len(set(nums))
    count = {}
    best = 0
    l = 0
    for r in range(len(nums)):
        x = nums[r]
        count[x] = count.get(x, 0) + 1
        while len(count) == need:
            length = r - l + 1
            if best == 0 or length < best:
                best = length
            count[nums[l]] -= 1
            if count[nums[l]] == 0:
                del count[nums[l]]
            l += 1
    return best

def range_sums(nums, queries):
    prefix = [0] * (len(nums) + 1)
    for i in range(len(nums)):
        prefix[i + 1] = prefix[i] + nums[i]
    answers = []
    for l, r in queries:
        if not 0 <= l <= r <= len(nums):
            raise ValueError("нужно 0 <= l <= r <= len(nums)")
        answers.append(prefix[r] - prefix[l])
    return answers

def pivot_index(nums):
    total = sum(nums)
    left = 0
    for i in range(len(nums)):
        right = total - left - nums[i]
        if left == right:
            return i
        left += nums[i]
    return -1

def count_k_sums(nums, k):
    seen = {0: 1}
    prefix = 0
    count = 0
    for r in range(len(nums)):
        prefix += nums[r]
        count += seen.get(prefix - k, 0)
        seen[prefix] = seen.get(prefix, 0) + 1
    return count

def ways_to_split(nums):
    total = sum(nums)
    left = 0
    count = 0
    for i in range(len(nums) - 1):
        left += nums[i]
        if left >= total - left:
            count += 1
    return count

def xor_queries(arr, queries):
    prefix = [0] * (len(arr) + 1)
    for i in range(len(arr)):
        prefix[i + 1] = prefix[i] ^ arr[i]
    answers = []
    for l, r in queries:
        answers.append(prefix[r + 1] ^ prefix[l])
    return answers

def nice_subarrays(nums, k):
    seen = {0: 1}
    odd = 0
    count = 0
    for r in range(len(nums)):
        odd += nums[r] % 2
        count += seen.get(odd - k, 0)
        seen[odd] = seen.get(odd, 0) + 1
    return count

def merge_intervals(intervals):
    ordered = sorted(intervals)
    merged = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def can_attend(intervals):
    ordered = sorted(intervals)
    for i in range(1, len(ordered)):
        if ordered[i][0] < ordered[i - 1][1]:
            return False
    return True

def insert_interval(intervals, new):
    start, end = new
    result = []
    i = 0
    while i < len(intervals) and intervals[i][1] < start:
        result.append(list(intervals[i]))
        i += 1
    while i < len(intervals) and intervals[i][0] <= end:
        start = min(start, intervals[i][0])
        end = max(end, intervals[i][1])
        i += 1
    result.append([start, end])
    while i < len(intervals):
        result.append(list(intervals[i]))
        i += 1
    return result

def remove_covered(intervals):
    ordered = sorted(intervals, key=lambda iv: (iv[0], -iv[1]))
    count = 0
    reach = 0
    for start, end in ordered:
        if end > reach:
            count += 1
            reach = end
    return count

def summary_ranges(nums):
    result = []
    i = 0
    while i < len(nums):
        j = i
        while j + 1 < len(nums) and nums[j + 1] == nums[j] + 1:
            j += 1
        if i == j:
            result.append(str(nums[i]))
        else:
            result.append(f"{nums[i]}->{nums[j]}")
        i = j + 1
    return result

def interval_intersections(first, second):
    result = []
    i = j = 0
    while i < len(first) and j < len(second):
        start = max(first[i][0], second[j][0])
        end = min(first[i][1], second[j][1])
        if start <= end:
            result.append([start, end])
        if first[i][1] < second[j][1]:
            i += 1
        else:
            j += 1
    return result

def car_points(nums):
    ordered = sorted(nums)
    total = 0
    reach = 0
    for start, end in ordered:
        if end > reach:
            total += end - max(start - 1, reach)
            reach = end
    return total
